INSERT INTO `jobs` (`Id`, `name`, `description`) VALUES
(1, 'D749', 'CSX Neville Island Switcher.\n- Demmler Yard: Pick up for Scully Yard\n- Demmler Yard: Pick up for Neville Island\n- South Yard: Set out inbound; Pick up for Demmler Yard\n- Demmler Yard: Set out outbound'),
(2, 'NVL', 'POHC Neville Local.\n- Scully Yard: Pick up for Neville Island and Demmler Yard\n- South Yard: Set out; Pick up Neville Island block\n- Neville Island: Spot and pull for island, Scully, and Demmler\n- South Yard: Set out; Pick up for Scully Yard\n- Scully Yard: Set out outbound'),
(3, 'SY1', 'South Yard yardmaster (SY1) — inter-island switching on Neville Island.\nRetrieve and stage cars across North, East, and West yards for island industries.\nSort inbound traffic and build outbound blocks for CSX D749 (via Demmler) and POHC NVL (via Scully).\nD749 and NVL handle industry spotting and interchange; SY1 works the satellite yards only.'),
(4, 'CK-1', 'Coke transfer — optional yard move.\nMove coke loads from East Yard to South Yard for weighing and classification when authorized and traffic warrants.\nRun only when it will not interfere with NVL or passenger movements.'),
(5, 'CKX', 'Coke extra — optional outbound coke move.\nDepart South Yard with weighed coke loads when enough cars are ready.\nMay run via CSX (Demmler) or POHC as directed by car routing.');
